DROP TABLE IF EXISTS `admin_db_slow_sql`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `admin_db_slow_sql` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `service_name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '服务名，如 product-service',
  `mapper_method` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'MappedStatement id，定位到 Mapper 方法',
  `sql_type` varchar(16) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'SELECT/INSERT/UPDATE/DELETE',
  `sql_fingerprint` char(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '归一化 SQL 的 MD5，用于聚合',
  `sql_text` text COLLATE utf8mb4_general_ci COMMENT '归一化 SQL，截断 2000 字符，不含参数值',
  `cost_ms` int NOT NULL COMMENT 'SQL 执行耗时（毫秒）',
  `row_count` int DEFAULT NULL COMMENT '返回/影响行数',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_fingerprint` (`sql_fingerprint`),
  KEY `idx_service_created` (`service_name`,`created_at`),
  KEY `idx_cost` (`cost_ms`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='慢 SQL 监控记录';
