--
-- Table structure for table `admin_menu`
--

DROP TABLE IF EXISTS `admin_menu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `admin_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '菜单 ID',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '父菜单 ID，0 为顶级',
  `menu_name` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称',
  `menu_type` char(1) COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型：M 目录 C 菜单 F 按钮',
  `path` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '前端路由路径',
  `component` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '前端组件路径（预留动态路由）',
  `perms` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '权限标识',
  `icon` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '图标',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序值',
  `visible` tinyint NOT NULL DEFAULT '1' COMMENT '是否显示：1 显示 0 隐藏',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1 正常 0 停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_admin_menu_parent` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1018 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='后台菜单与权限';
/*!40101 SET character_set_client = @saved_cs_client */;

