--
-- Table structure for table `admin_monitor_task`
--

DROP TABLE IF EXISTS `admin_monitor_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `admin_monitor_task` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务名称，页面展示用，唯一',
  `task_group` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'default' COMMENT '分组',
  `bean_name` varchar(200) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Spring Bean 名称',
  `method_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '执行方法名',
  `method_params` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '方法参数字符串',
  `task_type` tinyint NOT NULL DEFAULT '1' COMMENT '1 cron 2 fixedDelay 3 fixedRate',
  `schedule_value` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'cron 表达式，或 fixedDelay/fixedRate 的毫秒数',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '0 暂停 1 运行',
  `concurrent` tinyint NOT NULL DEFAULT '0' COMMENT '0 允许并发 1 禁止并发',
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_name` (`task_name`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='定时任务配置';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `admin_monitor_task`
--

LOCK TABLES `admin_monitor_task` WRITE;
/*!40000 ALTER TABLE `admin_monitor_task` DISABLE KEYS */;
