--
-- Table structure for table `admin_monitor_task_log`
--

DROP TABLE IF EXISTS `admin_monitor_task_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `admin_monitor_task_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_id` bigint unsigned NOT NULL COMMENT '任务ID',
  `task_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务名称冗余，任务删除后日志仍可读',
  `trigger_type` tinyint NOT NULL DEFAULT '1' COMMENT '1 定时触发 2 手动触发',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1 成功 0 失败',
  `error_msg` varchar(1024) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '失败原因',
  `cost_ms` int NOT NULL DEFAULT '0' COMMENT '耗时毫秒',
  `started_at` datetime NOT NULL COMMENT '开始时间',
  `finished_at` datetime DEFAULT NULL COMMENT '结束时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_task_started` (`task_id`,`started_at`),
  KEY `idx_started_at` (`started_at`)
) ENGINE=InnoDB AUTO_INCREMENT=12701 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='定时任务执行记录';
/*!40101 SET character_set_client = @saved_cs_client */;

