DROP TABLE IF EXISTS `after_sale_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `after_sale_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '售后变更日志ID',
  `after_sale_id` bigint NOT NULL COMMENT '售后单ID（不加外键，软删不影响日志留存）',
  `user_id` bigint NOT NULL DEFAULT '0' COMMENT '操作人ID（admin.id 或 user.id）',
  `user_type` tinyint NOT NULL DEFAULT '1' COMMENT '操作人类型：1买家 2后台管理员',
  `before_status` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '变更前状态（新建时 NULL）',
  `after_status` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '变更后状态',
  `operate_type` tinyint NOT NULL COMMENT '操作类型：见 AfterSaleOperateTypeEnum',
  `content` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT '公开说明（买家可见）',
  `merchant_remark` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商家内部备注（仅后台可见，买家接口不返回）',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除：0正常 1删除',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_after_sale_log_as_id` (`after_sale_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='售后变更流水日志表';
/*!40101 SET character_set_client = @saved_cs_client */;

