DROP TABLE IF EXISTS `after_sale_returns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `after_sale_returns` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '退货记录ID',
  `after_sale_id` bigint NOT NULL COMMENT '售后单ID',
  `return_way` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '退货方式：pickup上门取件 / self自行寄回',
  `return_time_slot` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '取件时段：morning上午 / afternoon下午',
  `return_at` datetime DEFAULT NULL COMMENT '发起退货时间',
  `review_at` datetime DEFAULT NULL COMMENT '审核时间',
  `rejected_at` datetime DEFAULT NULL COMMENT '驳回时间',
  `refund_at` datetime DEFAULT NULL COMMENT '发起退款时间',
  `refunded_at` datetime DEFAULT NULL COMMENT '退款完成时间',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除：0正常，1已删除',
  `return_courier` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '退货快递公司(英文code)',
  `return_tracking_number` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '退货快递单号',
  `pickup_at` datetime DEFAULT NULL COMMENT '买家确认上门取件时间',
  `pickup_no` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '模拟取件单号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_after_sale_returns_after_sale_id` (`after_sale_id`) USING BTREE,
  CONSTRAINT `fk_after_sale_returns_after_sale` FOREIGN KEY (`after_sale_id`) REFERENCES `after_sales` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='退货信息表';
