DROP TABLE IF EXISTS `after_sales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `after_sales` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '售后单ID',
  `order_id` bigint NOT NULL COMMENT '关联订单ID',
  `after_sale_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '售后单号',
  `order_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '原订单号',
  `after_sale_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'return_refund' COMMENT '售后类型：return_refund退货退款 / refund仅退款',
  `status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT '售后状态：pending待处理',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除 0正常 1删除',
  `reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '售后原因',
  `goods_status` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '货物状态：not_received 未收到货 / received 已收到货 / rejected 已拒收',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '买家备注',
  `images` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '[]' COMMENT '图片JSON数组',
  `merchant_remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '商家备注',
  `refund_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '退款金额快照',
  `refund_no` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '模拟退款单号',
  `refund_channel` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '退款渠道（取支付方式）',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_after_sales_created_at` (`created_at`) USING BTREE,
  KEY `idx_after_sales_order_id` (`order_id`) USING BTREE,
  KEY `idx_after_sales_status` (`status`) USING BTREE,
  CONSTRAINT `fk_after_sales_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=9118 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='售后单表';
/*!40101 SET character_set_client = @saved_cs_client */;

