DROP TABLE IF EXISTS `ai_chat_conversation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_chat_conversation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(256) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '新对话',
  `admin_id` bigint DEFAULT NULL COMMENT '后台对话发起人，商城为 NULL',
  `user_id` bigint DEFAULT NULL COMMENT '商城对话发起人，后台为 NULL',
  `anonymous_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '匿名访客标识（未登录用户）',
  `source` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'mall / admin',
  `role_id` bigint DEFAULT NULL,
  `system_message` varchar(1024) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `temperature` double NOT NULL DEFAULT '0.7',
  `max_tokens` int NOT NULL DEFAULT '2048',
  `max_contexts` int NOT NULL DEFAULT '20' COMMENT '保留的上下文轮数',
  `pinned` tinyint NOT NULL DEFAULT '0',
  `human_mode` tinyint NOT NULL DEFAULT '0' COMMENT '1=已转人工，AI 不再自动回复',
  `human_at` datetime DEFAULT NULL COMMENT '转人工时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_conv_admin` (`admin_id`,`source`),
  KEY `idx_conv_user` (`user_id`,`source`),
  KEY `idx_conv_anon` (`anonymous_id`,`source`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='AI 对话表';
/*!40101 SET character_set_client = @saved_cs_client */;

