DROP TABLE IF EXISTS `ai_chat_message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_chat_message` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `conversation_id` bigint NOT NULL,
  `admin_id` bigint DEFAULT NULL,
  `user_id` bigint DEFAULT NULL,
  `anonymous_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '匿名访客标识',
  `role_id` bigint DEFAULT NULL,
  `type` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'user / assistant / tool',
  `content` text COLLATE utf8mb4_general_ci,
  `tool_calls` text COLLATE utf8mb4_general_ci COMMENT 'assistant 发起的工具调用 JSON',
  `tool_call_id` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'type=tool 时',
  `tool_name` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'type=tool 时',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_msg_conv` (`conversation_id`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='AI 消息表';
