CREATE TABLE `ai_kb_qa` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `category` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类，用于同分类加权',
  `scope` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '客服' COMMENT '知识适用范围：客服/运营',
