  `answer` text COLLATE utf8mb4_general_ci NOT NULL COMMENT '答案原文，直接返回给用户',
  `keywords` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '关键词，逗号分隔',
  `priority` int NOT NULL DEFAULT '0' COMMENT '同分排序，越大越优先',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1 启用 0 停用',
