DROP TABLE IF EXISTS `ai_kb_segment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_kb_segment` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `dataset_id` bigint NOT NULL COMMENT '所属知识库',
  `source_doc` varchar(256) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源文档名',
  `title` varchar(256) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '分段标题',
  `content` text COLLATE utf8mb4_general_ci NOT NULL COMMENT '分段正文',
  `embedding` text COLLATE utf8mb4_general_ci COMMENT '向量 JSON 数组',
  `status` tinyint NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_segment_dataset` (`dataset_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='AI 运营知识分段表';
