--
-- Table structure for table `ai_tool`
--

DROP TABLE IF EXISTS `ai_tool`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_tool` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(128) COLLATE utf8mb4_general_ci NOT NULL COMMENT '工具名，与代码 @tool 函数名一致',
  `description` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '工具描述（给大模型看）',
  `perm_code` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '权限码，对应 admin_menu 一条 F 类型记录',
  `scope` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'both' COMMENT 'mall / admin / both',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1 启用 0 停用',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
