DROP TABLE IF EXISTS `cart`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cart` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '购物车项 ID',
  `user_id` bigint NOT NULL COMMENT '用户 ID',
  `product_id` bigint NOT NULL COMMENT '商品 ID',
  `sku_id` bigint DEFAULT NULL COMMENT 'SKU ID',
  `quantity` int NOT NULL DEFAULT '1' COMMENT '数量',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名快照',
  `image` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商品图快照',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '单价快照',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '商品描述快照',
  `insurance_detail` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '[]' COMMENT '保险详情 JSON（历史遗留，现为 "[]"）',
  `insurance_fee` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '保险费',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `spec_json` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '规格快照（展示用）',
  `sku_code` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商家编码快照',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_cart_user_sku` (`user_id`,`sku_id`),
  KEY `fk_cart_product` (`product_id`) USING BTREE,
  KEY `idx_cart_product` (`product_id`),
  KEY `idx_cart_user` (`user_id`),
  CONSTRAINT `fk_cart_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_cart_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='购物车';
