DROP TABLE IF EXISTS `order_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_items` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '订单项 ID',
  `order_id` bigint NOT NULL COMMENT '所属订单 ID',
  `product_id` bigint NOT NULL COMMENT '商品 ID（下单快照，订单历史不随商品删除，故不加外键）',
  `sku_id` bigint DEFAULT NULL COMMENT '下单时 SKU ID 快照',
  `product_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名快照',
  `image` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商品图快照',
  `sales_price` decimal(10,2) NOT NULL COMMENT '成交单价',
  `original_price` decimal(10,2) DEFAULT NULL COMMENT '原单价快照',
  `quantity` int NOT NULL COMMENT '购买数量',
  `sub_total` decimal(10,2) NOT NULL COMMENT '小计 = 单价 × 数量',
  `discount_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '该行优惠金额（含满减分摊）',
  `insurance_detail` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '[]' COMMENT '保险详情 JSON（历史遗留，现为 "[]"）',
  `insurance_fee` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '保险费',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除：1 已删除 0 正常',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `after_sale_status` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'none' COMMENT '售后标记：none/processing/refunded/exchanged/rejected',
  `after_sale_id` bigint DEFAULT NULL COMMENT '关联售后单 ID',
  `sku_code` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商家编码快照',
  `spec_json` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '下单时规格快照，如 颜色:曜石黑|存储容量:256G',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `fk_order_items_order` (`order_id`) USING BTREE,
  KEY `idx_order_items_after_sale_id` (`after_sale_id`),
  CONSTRAINT `fk_order_items_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=286 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='订单项';
