--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '下单用户 ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号（业务唯一，ORD+时间戳）',
  `pay_amount` decimal(10,2) DEFAULT NULL COMMENT '实付金额',
  `original_amount` decimal(10,2) DEFAULT NULL COMMENT '活动前金额（商品原价小计 + 保险）',
  `discount_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '优惠金额（直减 + 满减）',
  `coupon_id` bigint DEFAULT NULL COMMENT '使用的优惠券 ID',
  `coupon_name` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '优惠券名称快照',
  `coupon_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '优惠券优惠金额',
  `pay_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '支付方式：WeChat/Alipay/BankCard',
  `consignee` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收货人姓名快照',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收货人手机号快照',
  `region` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '省市区快照',
  `detail_address` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '详细地址快照',
  `order_status` tinyint NOT NULL DEFAULT '1' COMMENT '订单状态：1待付款 3待发货 4已发货 5已完成 6已取消',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除：1 已删除 0 正常',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '买家备注',
  `shipping_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '商家配送' COMMENT '配送方式（原 sqlite 默认值乱码，已还原为「商家配送」）',
  `courier` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '快递公司',
  `tracking_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '快递单号',
