  `unpaid_notify_sent` tinyint NOT NULL DEFAULT '0' COMMENT '未支付提醒是否已推送：1是 0否',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '下单时间',
  `pay_at` datetime DEFAULT NULL COMMENT '支付时间',
  `ship_at` datetime DEFAULT NULL COMMENT '发货时间',
  `finish_at` datetime DEFAULT NULL COMMENT '完成时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_orders_order_no` (`order_no`) USING BTREE,
  KEY `fk_orders_user` (`user_id`) USING BTREE,
  KEY `idx_orders_unpaid_notify` (`order_status`,`is_subscribe_unpaid`,`unpaid_notify_sent`,`created_at`),
  KEY `idx_orders_coupon` (`coupon_id`),
  CONSTRAINT `fk_orders_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=227 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='订单';
