--
-- Table structure for table `product_reviews`
--

DROP TABLE IF EXISTS `product_reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_reviews` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '评价 ID',
  `order_id` bigint NOT NULL COMMENT '所属订单 ID',
  `user_id` bigint NOT NULL COMMENT '评价用户 ID',
  `product_id` bigint NOT NULL COMMENT '商品 ID（快照，历史评价不随商品删，不加外键）',
  `product_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名快照',
  `product_image` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商品图快照',
  `rating` tinyint NOT NULL DEFAULT '5' COMMENT '星级：1~5',
  `tags` json DEFAULT NULL COMMENT '评价标签数组，最多 4 个',
  `content` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '评价内容',
  `images` varchar(2048) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '晒图 JSON 数组（可选）',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1 显示 0 隐藏',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除：1 已删除 0 正常',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '评价时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `reply` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商家回复',
  `reply_time` datetime DEFAULT NULL COMMENT '商家回复时间',
  `is_virtual` tinyint NOT NULL DEFAULT '0' COMMENT '是否虚拟评价：1 虚拟 0 买家真实',
  `created_by` bigint DEFAULT NULL COMMENT '虚拟评价创建人（后台管理员 admin.id）',
  PRIMARY KEY (`id`),
  KEY `idx_review_order` (`order_id`),
  KEY `idx_review_product` (`product_id`),
  KEY `idx_review_user` (`user_id`),
  KEY `idx_review_admin` (`is_deleted`,`status`,`created_at`),
  KEY `idx_review_product_show` (`product_id`,`status`,`is_deleted`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2554 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='商品评价';
/*!40101 SET character_set_client = @saved_cs_client */;

