--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '商品 ID',
  `title` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '商品标题',
  `category_id` bigint DEFAULT NULL COMMENT '分类 ID',
  `tag_id` bigint DEFAULT NULL COMMENT '标签 ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `sub_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '副标题',
  `brand` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '品牌',
  `stock` int NOT NULL DEFAULT '0' COMMENT '库存',
  `image` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '主图',
  `body` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '图文详情（富文本）',
  `sales_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'spot' COMMENT '销售模式：spot 现货',
  `listing_status` tinyint NOT NULL DEFAULT '1' COMMENT '上架状态：1 上架 0 下架',
  `sales_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '售价',
  `market_price` decimal(10,2) DEFAULT NULL COMMENT '市场价/划线价',
  `cost_price` decimal(10,2) DEFAULT NULL COMMENT '成本价（后台可见，C 端不下发）',
  `product_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商品编码',
  `specs` json DEFAULT NULL COMMENT '规格参数(JSON数组，非SKU)',
  `sku_type` tinyint NOT NULL DEFAULT '0' COMMENT '0 单规格 / 1 多规格',
  `sku_specs` text COLLATE utf8mb4_general_ci COMMENT '销售规格维度定义 JSON（引用规格字典）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `fk_products_tag` (`tag_id`) USING BTREE,
  KEY `fk_products_category` (`category_id`) USING BTREE,
  KEY `idx_products_list_status_cat_id` (`listing_status`,`category_id`,`id`),
  KEY `idx_products_list_status_price_id` (`listing_status`,`sales_price`,`id`),
  CONSTRAINT `fk_products_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_products_tag` FOREIGN KEY (`tag_id`) REFERENCES `tags` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=139 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品（单规格）';
/*!40101 SET character_set_client = @saved_cs_client */;

