--
-- Table structure for table `promotion`
--

DROP TABLE IF EXISTS `promotion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `promotion` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '活动 ID',
  `name` varchar(128) COLLATE utf8mb4_general_ci NOT NULL COMMENT '活动名称',
  `type` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型：DIRECT 直减 / FULL_REDUCE 满减',
  `rule_type` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '玩法：DISCOUNT 限时折扣 / NEW_USER 新用户专享 / FULL_AMOUNT_REDUCE 满额减 / FULL_AMOUNT_DISCOUNT 满额折',
  `target_group` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'ALL' COMMENT '目标人群：ALL 全部用户 / NEW_USER 未下单新用户',
  `scope_type` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PRODUCT' COMMENT '商品范围：ALL 全场 / PRODUCT 指定商品',
  `tag_name` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'C 端促销标签，如「限时立减」',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `manual_status` tinyint NOT NULL DEFAULT '0' COMMENT '运营状态：0 正常 1 提前结束',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除：1 已删除 0 正常',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_promotion_time` (`start_time`,`end_time`),
  KEY `idx_promotion_status` (`is_deleted`,`manual_status`)
) ENGINE=InnoDB AUTO_INCREMENT=9003 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='促销活动';
/*!40101 SET character_set_client = @saved_cs_client */;

