--
-- Table structure for table `promotion_article`
--

DROP TABLE IF EXISTS `promotion_article`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `promotion_article` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '文章 ID',
  `category_id` bigint NOT NULL DEFAULT '0' COMMENT '文章分类 ID，0 表示未分类',
  `title` varchar(128) COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题（唯一，逻辑删除后仍占用）',
  `author` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '作者',
  `cover` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '封面图地址',
  `content` longtext COLLATE utf8mb4_general_ci NOT NULL COMMENT '正文 HTML',
  `introduction` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '简介',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序，越小越靠前',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：1 启用 0 禁用',
  `recommend_hot` tinyint NOT NULL DEFAULT '0' COMMENT '是否热门（小程序推荐位）',
  `recommend_banner` tinyint NOT NULL DEFAULT '0' COMMENT '是否轮播（小程序文章轮播位）',
  `browse_count` int NOT NULL DEFAULT '0' COMMENT '浏览量',
  `spu_id` bigint NOT NULL DEFAULT '0' COMMENT '关联商品 ID，0 表示不关联',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0 正常 1 已删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_promotion_article_category` (`category_id`),
  KEY `idx_promotion_article_title` (`title`),
  KEY `idx_promotion_article_status` (`status`,`is_deleted`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='文章表';
