CREATE TABLE `promotion_banner` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Banner ID',
  `title` varchar(64) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题',
  `image` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片地址（相对路径，如 /image/banner/xxx.webp）',
  `images` text COLLATE utf8mb4_general_ci COMMENT '图片地址 JSON 数组（最多 4 张，首张与 image 相同）',
  `position` tinyint NOT NULL DEFAULT '1' COMMENT '广告位置：1 小程序首页 2 小程序分类页 11 PC商城首页',
  `link_type` tinyint NOT NULL DEFAULT '0' COMMENT '跳转类型：0 不跳转 1 商品 2 文章 3 外部链接',
  `link_value` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '跳转目标：商品ID / 文章ID / 外链URL',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序，越小越靠前',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1 启用 0 禁用',
  `browse_count` int NOT NULL DEFAULT '0' COMMENT '点击次数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_promotion_banner_query` (`position`,`status`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Banner 广告位表';
